export function s(
  id: PuzzleId,
  title: string,
  short: string,
  emoji: string,
  gradient: string,
  grade: Grade,
  subject: Subject,
  skill: string,
  estMin: number,
  interactionHint: Mode,
  options: {
    displayInteraction?: InteractionTypeKey;
    xpRequired?: number;
    isBoss?: boolean;
    isMasteryTest?: boolean;
    prerequisites?: PuzzleId[];
    unlockMessage?: string;
  } = {},
): PuzzleMeta {
  return {
    id,
    title,
    short,
    emoji,
    gradient,
    grade,
    subject,
    skill,
    estMin,
    interactionHint,
    ...options,
  };
}

